1	import Link from "next/link";
2	import {
3	  ArrowRight, Eye, FileSignature, FolderKanban, Heart, Inbox, KeyRound, LandPlot, MailWarning, MessagesSquare, Sparkles, TrendingUp,
4	} from "lucide-react";
5	import Button from "@/components/ui/Button";
6	import { Badge, Hinweis, Karte, Kennzahl, Leer, PfeilLink, SeitenKopf, StatusBadge, Stepper } from "@/components/Portal/ui";
7	import { portalNutzer, istAdmin } from "@/lib/plattform/server/seite";
8	import { backend } from "@/lib/plattform/backend";
9	import { rolleLabel, VORGANG_TYPEN, PROJEKT_TYPEN, LAENDER } from "@/lib/plattform/konstanten";
10	import { statusLabel } from "@/lib/plattform/prozesse";
11	import { datum, ha, mwp, preisText, relativ } from "@/lib/plattform/format";
12	import { fmt } from "@/lib/rechner/annahmen";
13	import { phaseById } from "@/lib/invest/markt";
14	import ErsteSchritte from "@/components/Portal/Bedienung/Onboarding/ErsteSchritte";
15	import { BriefcaseBusiness } from "lucide-react"; // Portfolio
16	import { portfolioBackend } from "@/lib/plattform/backend/portfolio"; // Portfolio
17	
18	export const metadata = { title: "Übersicht" };
19	
20	export default async function PortalStart({ searchParams }) {
21	  const n = await portalNutzer();
22	  const sp = await searchParams;
23	  const b = backend();
24	  // Rollenbereiche nur für tatsächlich gewählte Rollen (Admin sieht sein Cockpit separat)
25	  const hat = (...r) => r.some((x) => n.rollen.includes(x));
26	  const flaecheRolle = hat("flaeche", "landwirt");
27	  const anbieter = hat("anbieter");
28	  const investor = hat("investor");
29	  const admin = istAdmin(n);
30	
31	  const [vorgaenge, flaechen, projekte, interessen, boerse, threads, uebersicht] = await Promise.all([
32	    b.vorgaenge(n),
33	    flaecheRolle ? b.flaechen(n) : [],
34	    anbieter ? b.projekte(n) : [],
35	    investor ? b.interessen(n) : [],
36	    investor ? b.boerse(n) : null,
37	    b.nachrichtenThreads(n),
38	    admin ? b.adminUebersicht(n) : null,
39	  ]);
40	
41	  const ungelesen = threads.reduce((s, t) => s + t.ungelesen, 0);
42	  const offeneVorgaenge = vorgaenge.filter((v) => !["abgeschlossen", "abgelehnt", "zurueckgezogen"].includes(v.status));
43	  const passende = investor && boerse ? boerse.projekte.filter((p) => p.matching).sort((a, c) => c.matching.score - a.matching.score).slice(0, 3) : [];
44	  const datenraeume = interessen.filter((i) => ["nda_freigegeben", "loi_abgegeben", "loi_angenommen"].includes(i.status));
45	  const merkliste = interessen.filter((i) => i.gemerkt);
46	
47	  // ---------------------------------------------------------------- nächste Schritte
48	  const schritte = [];
49	  if (!n.emailBestaetigt) schritte.push({ icon: MailWarning, titel: "E-Mail-Adresse bestätigen", text: "Danach ordnen wir frühere Anfragen mit Ihrer Adresse automatisch zu.", href: "/portal/profil", cta: "Mehr erfahren" });
50	  for (const f of flaechen.filter((x) => x.status === "pachtangebot")) schritte.push({ icon: FileSignature, titel: `Pachtangebot prüfen: ${f.bezeichnung}`, text: "Ihr Angebot liegt vor. Annehmen oder Rückfrage stellen.", href: `/portal/flaechen/${f.id}`, cta: "Angebot ansehen" });
51	  for (const f of flaechen.filter((x) => x.status === "entwurf")) schritte.push({ icon: LandPlot, titel: `Fläche vervollständigen: ${f.bezeichnung}`, text: "Ergänzen Sie Ort und Größe und reichen Sie die Fläche zur Prüfung ein.", href: `/portal/flaechen/${f.id}`, cta: "Fläche ergänzen" });
52	  if (flaecheRolle && !flaechen.length) schritte.push({ icon: LandPlot, titel: "Erste Fläche hinzufügen", text: "Lage, Größe und Flurstücke genügen für eine kostenlose Vorprüfung.", href: "/portal/flaechen/neu", cta: "Fläche hinzufügen" });
53	  for (const p of projekte.filter((x) => x.status === "entwurf")) schritte.push({ icon: FolderKanban, titel: `Projekt einreichen: ${p.titel}`, text: p.provisionAkzeptiert ? "Angaben prüfen und zur Freigabe einreichen." : "Provisionsvereinbarung akzeptieren und einreichen.", href: `/portal/projekte/${p.id}`, cta: "Zum Projekt" });
54	  if (anbieter && !projekte.length) schritte.push({ icon: FolderKanban, titel: "Erstes Projekt anlegen", text: "Anonymer Teaser, vertraulicher Datenraum – Provision nur bei Abschluss.", href: "/portal/projekte/neu", cta: "Projekt anlegen" });
55	  if (investor && !n.suchprofil) schritte.push({ icon: Sparkles, titel: "Suchprofil anlegen", text: "Wir zeigen Ihnen passende Projekte mit Matching-Score.", href: "/portal/profil#suchprofil", cta: "Suchprofil anlegen" });
56	  for (const i of interessen.filter((x) => x.status === "nda_freigegeben")) schritte.push({ icon: KeyRound, titel: `Datenraum offen: ${i.projekt?.titel}`, text: "Unterlagen prüfen und bei Interesse eine LOI abgeben.", href: `/portal/boerse/${i.projektId}`, cta: "Zum Datenraum" });
57	  if (ungelesen) schritte.push({ icon: MessagesSquare, titel: `${ungelesen} ungelesene Nachricht${ungelesen === 1 ? "" : "en"}`, text: "Das Backoffice hat Ihnen geschrieben.", href: "/portal/nachrichten", cta: "Lesen" });
58	  if (!schritte.length) schritte.push({ icon: Inbox, titel: "Alles erledigt", text: "Aktuell ist nichts von Ihnen zu tun. Wir melden uns, sobald es weitergeht.", href: "/portal/anfragen", cta: "Anfragen ansehen" });
59	
60	  // ---------------------------------------------------------------- Kennzahlen
61	  const kacheln = [];
62	  if (flaecheRolle) kacheln.push({ label: "Flächen", wert: fmt(flaechen.length), hinweis: `${ha(flaechen.reduce((s, f) => s + (f.ha || 0), 0))} insgesamt`, icon: LandPlot, href: "/portal/flaechen" });
63	  if (anbieter) {
64	    kacheln.push({ label: "Projekte in der Börse", wert: fmt(projekte.filter((p) => ["veroeffentlicht", "reserviert"].includes(p.status)).length), hinweis: `${fmt(projekte.length)} Projekte gesamt`, icon: FolderKanban, href: "/portal/projekte" });
65	    kacheln.push({ label: "Aufrufe & Merker", wert: fmt(projekte.reduce((s, p) => s + p.statistik.aufrufe, 0)), hinweis: `${fmt(projekte.reduce((s, p) => s + p.statistik.merker, 0))} Merker · ${fmt(projekte.reduce((s, p) => s + p.statistik.ndaAnfragen, 0))} NDA-Anfragen`, icon: Eye, href: "/portal/projekte" });
66	  }
67	  if (investor) {
68	    kacheln.push({ label: "Passende Projekte", wert: fmt(boerse?.projekte.filter((p) => (p.matching?.score || 0) >= 70).length || 0), hinweis: n.suchprofil ? "Matching-Score ≥ 70" : "Suchprofil fehlt", icon: Sparkles, href: "/portal/boerse?sortierung=passung" });
69	    kacheln.push({ label: "Merkliste", wert: fmt(merkliste.length), hinweis: `${fmt(datenraeume.length)} Datenräume frei`, icon: Heart, href: "/portal/boerse?ansicht=merkliste" });
70	    const pf = await portfolioBackend().pfMeine(n).catch(() => null); // Portfolio: Positionen nach dem Kauf
71	    if (pf?.positionen.length) kacheln.push({ label: "Portfolio", wert: fmt(pf.kennzahlen.anzahl), hinweis: pf.kennzahlen.offeneAbrufe ? `${fmt(pf.kennzahlen.offeneAbrufe)} Kapitalabruf(e) offen` : `${fmt(pf.kennzahlen.mwp)} MWp anteilig`, icon: BriefcaseBusiness, href: "/portal/portfolio" });
72	  }
73	  kacheln.push({ label: "Offene Anfragen", wert: fmt(offeneVorgaenge.length), hinweis: `${fmt(vorgaenge.length)} gesamt`, icon: Inbox, href: "/portal/anfragen" });
74	  kacheln.push({ label: "Ungelesene Nachrichten", wert: fmt(ungelesen), hinweis: `${fmt(threads.length)} ${threads.length === 1 ? "Unterhaltung" : "Unterhaltungen"}`, icon: MessagesSquare, href: "/portal/nachrichten" });
75	
76	  // ---------------------------------------------------------------- Aktivität
77	  const aktivitaet = [
78	    ...flaechen.flatMap((f) => (f.statusVerlauf || []).map((e) => ({ ...e, art: "flaeche", titel: f.bezeichnung, href: `/portal/flaechen/${f.id}` }))),
79	    ...projekte.flatMap((p) => (p.statusVerlauf || []).map((e) => ({ ...e, art: "projekt", titel: p.titel, href: `/portal/projekte/${p.id}` }))),
80	    ...interessen.flatMap((i) => (i.statusVerlauf || []).map((e) => ({ ...e, art: "interesse", titel: i.projekt?.titel || i.projektId, href: `/portal/boerse/${i.projektId}` }))),
81	    ...vorgaenge.map((v) => ({ status: v.status, am: v.geaendertAm, art: "vorgang", titel: `Anfrage ${VORGANG_TYPEN[v.typ]}`, href: `/portal/anfragen/${v.id}`, kommentar: v.letzterKommentar })),
82	  ]
83	    .sort((a, c) => String(c.am).localeCompare(String(a.am)))
84	    .slice(0, 7);
85	
86	  const hinweis = sp?.hinweis;
87	
88	  return (
89	    <div className="space-y-6 md:space-y-8">
90	      <SeitenKopf
91	        eyebrow="Übersicht"
92	        titel={`Guten Tag, ${n.vorname}`}
93	        text="Hier sehen Sie den Stand all Ihrer Vorgänge, Flächen und Projekte – und was als Nächstes ansteht."
94	        aktionen={
95	          <div className="flex flex-wrap gap-1.5">
96	            {n.rollen.map((r) => (
97	              <Badge key={r} ton={r === "admin" ? "dunkel" : "neutral"}>{rolleLabel(r)}</Badge>
98	            ))}
99	          </div>
100	        }
101	      />
102	
103	      {hinweis === "email-bestaetigt" && <Hinweis ton="ok" titel="E-Mail-Adresse bestätigt">Vielen Dank. Frühere Anfragen mit dieser Adresse sind jetzt Ihrem Konto zugeordnet.</Hinweis>}
104	      {hinweis === "willkommen" && <Hinweis ton="ok" titel="Willkommen im Portal">Ihr Konto ist angelegt. Hier verfolgen Sie ab sofort alle Schritte.</Hinweis>}
105	      {hinweis === "einstieg-fertig" && <Hinweis ton="ok" titel="Einstieg abgeschlossen">Ihr Portal ist eingerichtet. Tipp: Mit Strg + K (Mac: ⌘ + K) finden Sie alles in Sekunden.</Hinweis>}
106	      <ErsteSchritte nutzer={n} />
107	
108	      <div className={`grid grid-cols-2 gap-3 sm:gap-4 ${kacheln.length >= 4 ? "xl:grid-cols-4" : "lg:grid-cols-3"}`}>
109	        {kacheln.slice(0, 4).map((k) => (
110	          <Kennzahl key={k.label} {...k} />
111	        ))}
112	      </div>
113	
114	      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)]">
115	        <div className="min-w-0 space-y-6">
116	          {/* Nächster Schritt */}
117	          <section aria-labelledby="naechster-schritt" className="ov-noise relative overflow-hidden rounded-3xl bg-navy-950 p-6 text-white md:p-7">
118	            <div aria-hidden="true" className="absolute -right-24 -top-24 h-64 w-64 rounded-full bg-ov-500/30 blur-[90px]" />
119	            <p id="naechster-schritt" className="relative text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-300">Nächster Schritt</p>
120	            <ul className="relative mt-4 space-y-3">
121	              {schritte.slice(0, 3).map((s, i) => {
122	                const Icon = s.icon;
123	                return (
124	                  <li key={`${s.titel}-${i}`} className="flex flex-col gap-3 rounded-2xl bg-white/[0.06] p-4 ring-1 ring-white/10 sm:flex-row sm:items-center">
125	                    <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-ov-500/20 text-ov-300">
126	                      <Icon aria-hidden="true" className="h-5 w-5" />
127	                    </span>
128	                    <div className="min-w-0 flex-1">
129	                      <p className="font-semibold leading-snug">{s.titel}</p>
130	                      <p className="mt-0.5 text-[13.5px] leading-relaxed text-white/65">{s.text}</p>
131	                    </div>
132	                    <Button href={s.href} size="sm" variant={i === 0 ? "primary" : "outlineLight"} pfeil={i === 0}>
133	                      {s.cta}
134	                    </Button>
135	                  </li>
136	                );
137	              })}
138	            </ul>
139	          </section>
140	
141	          {admin && uebersicht && (
142	            <Karte titel="Backoffice" untertitel="Was heute auf dem Tisch liegt" aktion={<PfeilLink href="/portal/admin">Zum Cockpit</PfeilLink>}>
143	              <div className="grid gap-3 sm:grid-cols-4">
144	                {[
145	                  { label: "Neue Vorgänge (7 Tage)", wert: uebersicht.vorgaenge.neu7, href: "/portal/admin/vorgaenge?status=eingegangen" },
146	                  { label: "Projekte in Prüfung", wert: uebersicht.projekte.inPruefung, href: "/portal/admin/projekte" },
147	                  { label: "NDA-Anfragen offen", wert: uebersicht.interessen.ndaOffen, href: "/portal/admin/interessen" },
148	                  { label: "Ungelesene Nachrichten", wert: uebersicht.nachrichten.ungelesen, href: "/portal/nachrichten" },
149	                ].map((k) => (
150	                  <Link key={k.label} href={k.href} className="rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60 hover:ring-ov-300">
151	                    <p className="ov-num font-display text-[24px] font-extrabold text-ink-900">{fmt(k.wert)}</p>
152	                    <p className="mt-1 text-[12.5px] leading-snug text-ink-600">{k.label}</p>
153	                  </Link>
154	                ))}
155	              </div>
156	            </Karte>
157	          )}
158	
159	          {flaecheRolle && (
160	            <Karte titel="Meine Flächen" aktion={<PfeilLink href="/portal/flaechen">Alle Flächen</PfeilLink>}>
161	              {flaechen.length ? (
162	                <ul className="space-y-5">
163	                  {flaechen.slice(0, 4).map((f) => (
164	                    <li key={f.id}>
165	                      <div className="flex flex-wrap items-center justify-between gap-2">
166	                        <Link href={`/portal/flaechen/${f.id}`} className="font-semibold text-ink-900 hover:text-ov-700">{f.bezeichnung}</Link>
167	                        <StatusBadge art="flaeche" status={f.status} />
168	                      </div>
169	                      <p className="mb-2.5 mt-0.5 text-[13px] text-ink-500">{[ha(f.ha), [f.plz, f.ort].filter(Boolean).join(" "), f.agri ? "Agri-PV" : null].filter(Boolean).join(" · ")}</p>
170	                      <Stepper art="flaeche" status={f.status} kompakt />
171	                    </li>
172	                  ))}
173	                </ul>
174	              ) : (
175	                <Leer icon={LandPlot} titel="Noch keine Fläche" text="Fügen Sie Ihre erste Fläche hinzu – die Vorprüfung ist kostenlos." aktion={<Button href="/portal/flaechen/neu" size="sm" pfeil>Fläche hinzufügen</Button>} />
176	              )}
177	            </Karte>
178	          )}
179	
180	          {anbieter && (
181	            <Karte titel="Meine Projekte" aktion={<PfeilLink href="/portal/projekte">Alle Projekte</PfeilLink>}>
182	              {projekte.length ? (
183	                <ul className="divide-y divide-ink-100">
184	                  {projekte.slice(0, 5).map((p) => (
185	                    <li key={p.id} className="flex flex-col gap-2 py-3 first:pt-0 last:pb-0 sm:flex-row sm:items-center">
186	                      <div className="min-w-0 flex-1">
187	                        <Link href={`/portal/projekte/${p.id}`} className="font-semibold text-ink-900 hover:text-ov-700">{p.titel}</Link>
188	                        <p className="text-[13px] text-ink-500">{[PROJEKT_TYPEN[p.typ], mwp(p.mwp), phaseById(p.phase)?.kurz].filter(Boolean).join(" · ")}</p>
189	                      </div>
190	                      <p className="flex gap-3 text-[12.5px] text-ink-500">
191	                        <span><Eye aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" />{fmt(p.statistik.aufrufe)}</span>
192	                        <span><Heart aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" />{fmt(p.statistik.merker)}</span>
193	                        <span><KeyRound aria-hidden="true" className="mr-1 inline h-3.5 w-3.5" />{fmt(p.statistik.ndaAnfragen)}</span>
194	                      </p>
195	                      <StatusBadge art="projekt" status={p.status} />
196	                    </li>
197	                  ))}
198	                </ul>
199	              ) : (
200	                <Leer icon={FolderKanban} titel="Noch kein Projekt" text="Stellen Sie Ihr erstes Projekt in die Börse – geprüft und vertraulich." aktion={<Button href="/portal/projekte/neu" size="sm" pfeil>Projekt anlegen</Button>} />
201	              )}
202	            </Karte>
203	          )}
204	
205	          {investor && (
206	            <Karte titel="Passende Projekte" untertitel={n.suchprofil ? "Nach Ihrem Suchprofil" : "Legen Sie ein Suchprofil an, um Projekte nach Passung zu sortieren."} aktion={<PfeilLink href="/portal/boerse">Zur Börse</PfeilLink>}>
207	              {passende.length ? (
208	                <ul className="grid gap-3 md:grid-cols-3">
209	                  {passende.map((p) => (
210	                    <li key={p.id}>
211	                      <Link href={`/portal/boerse/${p.id}`} className="flex h-full flex-col rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60 hover:ring-ov-300">
212	                        <span className="flex flex-wrap items-center justify-between gap-x-2 gap-y-1">
213	                          <Badge ton={p.matching.score >= 70 ? "ok" : "neutral"}>{p.matching.score} % Passung</Badge>
214	                          <span className="text-[12px] text-ink-500">{LAENDER[p.land]}</span>
215	                        </span>
216	                        <span className="mt-3 font-semibold leading-snug text-ink-900">{p.titel}</span>
217	                        <span className="mt-auto pt-3 text-[13px] text-ink-600">{mwp(p.mwp)} · {phaseById(p.phase).kurz} · {preisText(p)}</span>
218	                      </Link>
219	                    </li>
220	                  ))}
221	                </ul>
222	              ) : (
223	                <Leer icon={TrendingUp} titel="Suchprofil anlegen" text="Größe, Phasen, Länder und Ticket – dann zeigen wir Ihnen die passenden Projekte zuerst." aktion={<Button href="/portal/profil#suchprofil" size="sm" pfeil>Suchprofil anlegen</Button>} />
224	              )}
225	            </Karte>
226	          )}
227	
228	          <Karte titel="Meine Anfragen" aktion={<PfeilLink href="/portal/anfragen">Alle Anfragen</PfeilLink>}>
229	            {vorgaenge.length ? (
230	              <ul className="divide-y divide-ink-100">
231	                {vorgaenge.slice(0, 5).map((v) => (
232	                  <li key={v.id} className="flex flex-wrap items-center gap-x-3 gap-y-1 py-3 first:pt-0 last:pb-0">
233	                    <Link href={`/portal/anfragen/${v.id}`} className="min-w-0 flex-1 font-semibold text-ink-900 hover:text-ov-700">
234	                      {VORGANG_TYPEN[v.typ]} <span className="ov-num block text-[12.5px] font-normal text-ink-500 sm:inline sm:text-[inherit]"><span className="hidden sm:inline"> · </span>{v.id}</span>
235	                    </Link>
236	                    <span className="text-[12.5px] text-ink-500">{datum(v.erstelltAm)}</span>
237	                    <StatusBadge art="vorgang" status={v.status} />
238	                  </li>
239	                ))}
240	              </ul>
241	            ) : (
242	              <Leer icon={Inbox} titel="Keine Anfragen" text="Anfragen, die Sie über die Website senden, erscheinen hier – mit Status und Nachrichten." />
243	            )}
244	          </Karte>
245	        </div>
246	
247	        <div className="min-w-0 space-y-6">
248	          <Karte titel="Letzte Nachrichten" aktion={<PfeilLink href="/portal/nachrichten">Alle</PfeilLink>}>
249	            {threads.length ? (
250	              <ul className="space-y-1">
251	                {threads.slice(0, 5).map((t) => (
252	                  <li key={`${t.bezugArt}:${t.bezugId}`}>
253	                    <Link href={`/portal/nachrichten?bezug=${t.bezugArt}:${t.bezugId}`} className="-mx-2 flex gap-3 rounded-xl p-2 hover:bg-sand-50">
254	                      <span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${t.ungelesen ? "bg-ov-500" : "bg-transparent"}`} aria-hidden="true" />
255	                      <span className="min-w-0 flex-1">
256	                        <span className="flex items-baseline justify-between gap-2">
257	                          <span className={`truncate text-[14px] ${t.ungelesen ? "font-bold text-ink-900" : "font-semibold text-ink-800"}`}>{t.titel}</span>
258	                          <span className="shrink-0 text-[11.5px] text-ink-400">{relativ(t.letzte.am)}</span>
259	                        </span>
260	                        <span className="line-clamp-2 text-[13px] leading-snug text-ink-500">{t.letzte.text}</span>
261	                      </span>
262	                    </Link>
263	                  </li>
264	                ))}
265	              </ul>
266	            ) : (
267	              <p className="text-[14px] text-ink-500">Noch keine Nachrichten.</p>
268	            )}
269	          </Karte>
270	
271	          <Karte titel="Status-Timeline" untertitel="Letzte Änderungen an Ihren Vorgängen">
272	            {aktivitaet.length ? (
273	              <ol className="relative space-y-4 pl-6">
274	                <span aria-hidden="true" className="absolute bottom-1 left-[7px] top-1 w-px bg-ink-200" />
275	                {aktivitaet.map((a, i) => (
276	                  <li key={`${a.href}-${a.am}-${i}`} className="relative">
277	                    <span aria-hidden="true" className={`absolute -left-6 top-1 h-[15px] w-[15px] rounded-full ring-4 ring-white ${i === 0 ? "bg-ov-500" : "bg-ink-200"}`} />
278	                    <Link href={a.href} className="block text-[14px] font-semibold leading-snug text-ink-900 hover:text-ov-700">{a.titel}</Link>
279	                    <p className="text-[12.5px] text-ink-500">
280	                      {statusLabel(a.art, a.status)} · {relativ(a.am)}
281	                    </p>
282	                  </li>
283	                ))}
284	              </ol>
285	            ) : (
