.ov-press { transition: transform var(--ov-dauer-s) var(--ov-ease-out); }
@media (prefers-reduced-motion: no-preference) {
  .ov-press:active { transform: scale(0.975); transition-duration: 60ms; }
}

/* Stagger: Kinder erscheinen nacheinander, sobald der Elternblock sichtbar
   wird (RevealObserver setzt is-visible). Der Elternblock selbst bleibt
   stehen. Index automatisch bis 12 Kinder oder per style="--i: n". */
.ov-stagger > * {
  transition:
    opacity var(--ov-dauer-l) var(--ov-ease-out),
    transform var(--ov-dauer-l) var(--ov-ease-out);
  transition-delay: calc(var(--i, 0) * var(--ov-stagger) + var(--ov-delay, 0ms));
}
.ov-stagger > :nth-child(2) { --i: 1; }
.ov-stagger > :nth-child(3) { --i: 2; }
.ov-stagger > :nth-child(4) { --i: 3; }
.ov-stagger > :nth-child(5) { --i: 4; }
.ov-stagger > :nth-child(6) { --i: 5; }
.ov-stagger > :nth-child(7) { --i: 6; }
.ov-stagger > :nth-child(8) { --i: 7; }
.ov-stagger > :nth-child(9) { --i: 8; }
.ov-stagger > :nth-child(10) { --i: 9; }
.ov-stagger > :nth-child(11) { --i: 10; }
.ov-stagger > :nth-child(n + 12) { --i: 11; }
.js-ready .ov-stagger:not(.is-visible) > * { opacity: 0; transform: translate3d(0, 16px, 0); }
@media (prefers-reduced-motion: reduce) {
  .js-ready .ov-stagger:not(.is-visible) > * { opacity: 1; transform: none; }
}

/* Einmalige Einstiege (beim Mounten, ohne Observer) */
@keyframes ov-einblenden { from { opacity: 0.001; } to { opacity: 1; } }
@keyframes ov-auftauchen { from { opacity: 0.001; transform: translate3d(0, 12px, 0); } to { opacity: 1; transform: none; } }
@keyframes ov-skalieren { from { opacity: 0.001; transform: scale(0.96); } to { opacity: 1; transform: none; } }
@keyframes ov-ping { 0% { transform: scale(1); opacity: 0.55; } 80%, 100% { transform: scale(2.6); opacity: 0; } }
@keyframes ov-drehen { to { transform: rotate(360deg); } }
.ov-ein { animation: ov-auftauchen var(--ov-dauer-l) var(--ov-ease-out) both; animation-delay: var(--ov-delay, 0ms); }

/* Live-Punkt mit Ping (transform statt box-shadow) */
.ov-live-punkt { position: relative; display: inline-block; width: 0.5rem; height: 0.5rem; border-radius: 9999px; background: var(--color-ov-400); }
.ov-live-punkt::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: inherit; animation: ov-ping 1.8s var(--ov-ease-out) infinite; }
.ov-toast-aus { animation: ov-toast-aus 200ms var(--ov-ease-in-out) both; }
.ov-tooltip { animation: ov-tooltip-ein var(--ov-dauer-s) var(--ov-ease-out) both; }

/* Tabs: Indikator gleitet per transform (Breite per scaleX) */
.ov-tab-indikator {
  position: absolute;
  left: 0;
  width: 100px;
  transform-origin: 0 50%;
  transition: transform var(--ov-dauer-m) var(--ov-ease-out);
}
}

/* Muss den (ungelayerten) Reveal-Startzustand schlagen: Stagger-Eltern und
