      <ul className={cn("mx-auto grid max-w-[560px]", ziele.length === 3 ? "grid-cols-4" : "grid-cols-5")}>
        {ziele.map((z) => {
          const ist = aktiv(pfad, z.href, z.exakt);
          const Icon = z.icon;
          const zaehler = z.id === "nav-nachrichten" && ungelesen > 0 ? ungelesen : 0;
          return (
