        >
          <span className="absolute left-1/2 top-0 h-[3px] w-7 -translate-x-1/2 rounded-b-full bg-ov-600" />
          <span className="absolute left-1/2 top-[9px] h-7 w-12 -translate-x-1/2 rounded-full bg-ov-50" />
