1	import { Check, ExternalLink, FileDown, FolderLock, Gavel, Lock } from "lucide-react";
2	import Begriff from "@/components/Portal/Bedienung/Begriff";
3	import DateiLink from "@/components/Portal/DateiLink";
4	import { QualitaetsBalken } from "@/components/Portal/ui";
5	import Button from "@/components/ui/Button";
6	import TypIllustration from "@/components/Boerse/TypIllustration";
7	import { PhaseBadge } from "@/components/Boerse/ProjektKarte";
8	import MerkenKnopf from "@/components/Boerse/MerkenKnopf";
9	import NdaAnfrage from "@/components/Boerse/NdaAnfrage";
10	import StatusAktionen from "@/components/Portal/StatusAktionen";
11	import NachrichtenThread from "@/components/Portal/NachrichtenThread";
12	import KiFrage from "@/components/Portal/Ki/KiFrage";
13	import { DokumentListe } from "@/components/Portal/Dokumente";
14	import { Angaben, Badge, Hinweis, Karte, SeitenKopf, StatusBadge, Timeline } from "@/components/Portal/ui";
15	import { portalNutzer, laden } from "@/lib/plattform/server/seite";
16	import { backend } from "@/lib/plattform/backend";
17	import { LAENDER, NETZANSCHLUSS, PROJEKT_TYPEN } from "@/lib/plattform/konstanten";
18	import { VERTRAULICH_FELDER } from "@/lib/plattform/oeffentlich";
19	import { statusInfo } from "@/lib/plattform/prozesse";
20	import { datumZeit, eur, mwp, preisText } from "@/lib/plattform/format";
21	import { fmt } from "@/lib/rechner/annahmen";
22	import { phaseById } from "@/lib/invest/markt";
23	import KycHinweisServer from "@/components/Portal/Kyc/KycHinweisServer"; // KYC/KYB: Hinweis vor Datenraum-Freigabe
24	// Fachprüfung Kapitalseite: Datenblatt, Due-Diligence-Index, Bewertungswerkzeug, strukturierte LOI, Suchprofil-Passung
25	import { Calculator } from "lucide-react";
26	import { DatenblattAnzeige, DdIndexKarte } from "@/components/Portal/Fach/DdIndex";
27	import LoiFormular from "@/components/Portal/Fach/LoiFormular";
28	import { loiZeilen } from "@/lib/plattform/fach/loi";
29	import { passungHinweise } from "@/lib/plattform/fach/suchprofil";
30	import AnbieterAkte from "@/components/Portal/Anbieter/AnbieterAkte"; // Anbieter: Bestandsanlage (Ist-Daten) nach NDA
31	import { anbieterBackend } from "@/lib/plattform/backend/anbieter";
32	
33	export const metadata = { title: "Exposé" };
34	
35	export default async function PortalExpose({ params }) {
36	  const { id } = await params;
37	  const n = await portalNutzer({ rollen: ["investor"] });
38	  const b = backend();
39	  const d = await laden(() => b.boerseDetail(n, id, { zaehlen: true }));
40	  const p = d.projekt;
41	  const i = d.interesse;
42	  const thread = i ? await b.nachrichten(n, "interesse", i.id) : null;
43	  const phase = phaseById(p.phase);
44	  const frei = d.zugriff !== "oeffentlich";
45	  const bestandAkte = frei && p.phase === "cod" ? await anbieterBackend().anbieterAkte(n, p.id).catch(() => null) : null; // Bestandsanlage: Ertragshistorie, Verträge, Förderung, DD
46	
47	  return (
48	    <div className="space-y-6">
49	      <SeitenKopf
50	        eyebrow="Exposé"
51	        titel={p.titel}
52	        text={[PROJEKT_TYPEN[p.typ], mwp(p.mwp), p.region, LAENDER[p.land]].filter(Boolean).join(" · ")}
53	        aktionen={
54	          <>
55	            {i && i.status !== "gemerkt" && <StatusBadge art="interesse" status={i.status} className="text-[13px]" />}
56	            <MerkenKnopf projektId={p.id} gemerkt={!!i?.gemerkt} mitText />
57	            {frei ? (
58	              <>
59	                <Button href={`/portal/dealroom/${p.id}`} size="sm" variant="navy" icon={Gavel}>Deal-Room</Button>
60	                <Button href={`/portal/boerse/${p.id}/bewertung`} size="sm" variant="secondary" icon={Calculator}>Bewerten</Button>
61	                <Button href={`/portal/finanzierung?projekt=${p.id}`} size="sm" variant="secondary" icon={Calculator}>Finanzierung</Button>{/* Finanzierungscockpit */}
62	                <DateiLink href={`/api/portal/projekte/${p.id}/expose`} icon={FileDown} variant="primary">Exposé (PDF)</DateiLink>
63	              </>
64	            ) : (
65	              p.slug && <DateiLink href={`/api/boerse/${p.slug}/teaser`} icon={FileDown} neuesFenster>Teaser (PDF)</DateiLink>
66	            )}
67	            {p.slug && <Button href={`/projektboerse/${p.slug}`} size="sm" variant="ghost" icon={ExternalLink}>Öffentlich</Button>}
68	          </>
69	        }
70	      />
71	      {p.demo && <Hinweis ton="warn">Demo-Projekt – alle Angaben sind fiktiv.</Hinweis>}
72	
73	      <div className="grid gap-6 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
74	        <div className="min-w-0 space-y-6">
75	          <div className="overflow-hidden rounded-3xl bg-white ring-1 ring-ink-200/70">
76	            <div className="relative">
77	              <TypIllustration typ={p.typ} className="h-40 w-full" />
78	              <div className="absolute left-4 top-4 flex gap-2">
79	                <PhaseBadge phase={p.phase} />
80	                {p.status === "reserviert" && <Badge ton="dunkel">Reserviert</Badge>}
81	              </div>
82	            </div>
83	            <div className="p-5 md:p-6">
84	              <p className="whitespace-pre-line text-[15px] leading-relaxed text-ink-700">{p.beschreibung}</p>
85	              {p.highlights?.length > 0 && (
86	                <ul className="mt-4 grid gap-2 sm:grid-cols-2">
87	                  {p.highlights.map((h) => (
88	                    <li key={h} className="flex items-start gap-2 text-[14px] text-ink-700"><Check aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" />{h}</li>
89	                  ))}
90	                </ul>
91	              )}
92	              {typeof p.datenraumQualitaet === "number" && (
93	                <div className="mt-5 max-w-sm">
94	                  <QualitaetsBalken quote={p.datenraumQualitaet} />
95	                </div>
96	              )}
97	              <div className="mt-6 border-t border-ink-100 pt-5">
98	                <Angaben
99	                  spalten={3}
100	                  items={[
101	                    { label: "Leistung", wert: `${mwp(p.mwp)}${p.mwhSpeicher ? ` · ${fmt(p.mwhSpeicher)} MWh` : ""}` },
102	                    { label: "Phase", wert: phase.label },
103	                    { label: "Netzanschluss", wert: NETZANSCHLUSS[p.netzanschluss] },
104	                    { label: "COD geplant", wert: p.codGeplant },
105	                    { label: "Preisindikation", wert: preisText(p) },
106	                    { label: "Fläche", wert: p.flaecheHa ? `${fmt(p.flaecheHa, 1)} ha` : "" },
107	                    { label: "Region", wert: [p.region, p.bundesland].filter(Boolean).join(", ") },
108	                    { label: "Marktspanne der Phase", wert: `${fmt(phase.preisProKwp.min)}–${fmt(phase.preisProKwp.max)} €/kWp` },
109	                    { label: "Risiko (typisch)", wert: phase.risiko },
110	                  ]}
111	                />
112	              </div>
113	            </div>
114	          </div>
115	
116	          <Karte titel="Vertrauliche Angaben" aktion={frei ? <Badge ton="ok">Freigeschaltet</Badge> : <Lock aria-hidden="true" className="h-5 w-5 text-ink-400" />}>
117	            {frei ? (
118	              Object.keys(d.vertraulich || {}).length ? (
119	                <Angaben items={Object.entries(d.vertraulich).map(([k, w]) => ({ label: VERTRAULICH_FELDER[k] || k, wert: String(w), breit: k === "details" }))} />
120	              ) : (
121	                <p className="text-[14px] text-ink-500">Der Anbieter hat noch keine vertraulichen Angaben hinterlegt – Unterlagen finden Sie im Datenraum.</p>
122	              )
123	            ) : (
124	              <p className="text-[14.5px] leading-relaxed text-ink-600">Gemeinde, Flurstücke, Netzbetreiber, Einspeisepunkt, Ertrag und Unterlagen werden sichtbar, sobald das Backoffice Ihre NDA-Anfrage freigegeben hat.</p>
125	            )}
126	          </Karte>
127	
128	          {frei && <DatenblattAnzeige projekt={{ ...p, vertraulich: d.vertraulich || {}, datenblatt: d.datenblatt || {} }} untertitel="Angaben des Anbieters – Wirtschaftlichkeit ungeprüft" />}
129	          {bestandAkte && <AnbieterAkte akte={bestandAkte} />}
130	
131	          {frei && <KiFrage projektId={p.id} />}
132	
133	          {i && thread && (
134	            <Karte id="projekt-nachrichten" titel="Nachrichten zu diesem Projekt" untertitel="Fragen zum Projekt beantwortet das Backoffice – der Anbieter bleibt bis zur Freigabe anonym.">
135	              <NachrichtenThread bezugArt="interesse" bezugId={i.id} nachrichten={thread.nachrichten} />
136	            </Karte>
137	          )}
138	        </div>
139	
140	        <div className="min-w-0 space-y-6">
141	          {!frei && <KycHinweisServer schritt="nda" nutzer={n} />}
142	          {(() => {
143	            const h = passungHinweise(p, n.suchprofil, frei ? d.datenblatt : null);
144	            return h.passt.length || h.pruefen.length ? (
145	              <Karte titel="Passung zu Ihrem Suchprofil" untertitel={p.matching ? `Matching-Score ${p.matching.score} %` : undefined}>
146	                <ul className="space-y-1.5 text-[14px]">
147	                  {h.passt.map((x) => <li key={x} className="flex items-start gap-2 text-ink-800"><Check aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-ov-600" />{x}</li>)}
148	                  {h.pruefen.map((x) => <li key={x} className="flex items-start gap-2 text-ink-700"><span aria-hidden="true" className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-sun-400" />{x}</li>)}
149	                </ul>
150	              </Karte>
151	            ) : null;
152	          })()}
153	          {frei && d.ddIndex && <DdIndexKarte index={d.ddIndex} kompakt aktion={<Button href={`/portal/boerse/${p.id}/bewertung`} size="sm" variant="ghost" icon={Calculator}>Bewerten</Button>} />}
154	          {(!i || i.status === "gemerkt") && (
155	            <Karte titel={<>Datenraum anfragen <Begriff id="nda" nurIcon /></>}>
156	              {p.status === "reserviert" && <p className="mb-4 text-[13.5px] text-ink-600">Das Projekt ist reserviert. Sie können trotzdem Interesse anmelden – falls die Gespräche scheitern, melden wir uns.</p>}
157	              <NdaAnfrage projektId={p.id} />
158	            </Karte>
159	          )}
160	          {i && i.status === "nda_angefragt" && (
161	            <Hinweis ton="warn" titel="NDA-Anfrage liegt vor">
162	              Sie haben die Vertraulichkeitsvereinbarung am {datumZeit(i.nda?.am)} akzeptiert. Das Backoffice prüft die Freigabe – in der Regel innerhalb von zwei Werktagen.
163	            </Hinweis>
164	          )}
165	          {frei && (
166	            <Karte titel={<>Datenraum <Begriff id="datenraum" nurIcon /></>} aktion={<FolderLock aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
167	              <DokumentListe dokumente={d.dokumente} nutzerId={n.id} leerText="Noch keine Unterlagen im Datenraum." />
168	              <p className="mt-3 text-[12.5px] text-ink-500">Zugriffe werden protokolliert. Weitergabe nur gemäß NDA. Das Exposé-PDF enthält Ihren Namen als Empfänger.</p>
169	            </Karte>
170	          )}
171	          {i && ["nda_freigegeben", "loi_abgegeben", "loi_angenommen", "abgeschlossen", "abgelehnt"].includes(i.status) && (
172	            <Karte titel={<>Absichtserklärung (LOI) <Begriff id="loi" nurIcon /></>}>
173	              {i.loi ? (
174	                <Angaben spalten={1} items={[{ label: "Abgegeben", wert: datumZeit(i.loi.am) }, ...loiZeilen(i.loi)]} />
175	              ) : i.status === "nda_freigegeben" ? (
176	                <>
177	                  <p className="mb-4 text-[14px] leading-relaxed text-ink-600">Nach Prüfung des Datenraums geben Sie hier eine unverbindliche Absichtserklärung ab – mit Preisbasis, Struktur, Bedingungen und Exklusivität wie im Markt üblich. Tipp: Rechnen Sie Ihr Angebot vorher im <a href={`/portal/boerse/${p.id}/bewertung`} className="font-semibold text-ov-700 hover:text-ov-800">Bewertungswerkzeug</a>.</p>
178	                  <KycHinweisServer schritt="loi" nutzer={n} />
179	                  <LoiFormular interesseId={i.id} mwp={p.mwp} vorschlag={p.preisModus === "proKwp" ? { preisProKwp: p.preisProKwp } : p.preisModus === "gesamt" ? { betrag: p.preis } : null} />
180	                </>
181	              ) : (
182	                <p className="mb-4 text-[14px] leading-relaxed text-ink-600">Nach Prüfung des Datenraums können Sie hier eine unverbindliche Absichtserklärung abgeben.</p>
183	              )}
184	              {i.status !== "nda_freigegeben" && <StatusAktionen art="interesse" id={i.id} status={i.status} als="eigentuemer" className={i.loi ? "mt-4" : ""} />}
185	              <p className="mt-4 text-[13.5px] text-ink-500">{statusInfo("interesse", i.status).text}</p>
186	            </Karte>
187	          )}
188	          {i && (
189	            <Karte titel="Verlauf">
190	              <Timeline art="interesse" verlauf={i.statusVerlauf} />
191	            </Karte>
192	          )}
193	        </div>
194	      </div>
195	    </div>
196	  );
197	}
