// T3: Portal-Rahmen prüfen (Seitenleiste einklappen, Vorab-Zustand, Dashboards, mobil)
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const B = "http://localhost:3100";
const ziel = (n) => fileURLToPath(new URL("./shots/" + n, import.meta.url));
const nurPfade = process.argv.slice(2);
const b = await chromium.launch();
async function konto(email, breite) {
  const ctx = await b.newContext({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B } });
  console.log("login", email, r.status());
  return ctx;
}
async function seite(ctx, pfad) {
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 400)));
  const res = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(1500);
  const ueber = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  console.log(res.status(), pfad, ueber > 0 ? "UEBERLAUF " + ueber : "", fehler.length ? "\n  " + fehler.join("\n  ") : "");
  return p;
}
try {
  const modus = nurPfade[0] || "alles";
  if (modus === "alles" || modus === "admin") {
    const ctx = await konto("admin@example.com", 1440);
    let p = await seite(ctx, "/portal/admin");
    await p.screenshot({ path: ziel("t3_admin_1440.png") });
    // einklappen per Taste, dann neu laden: Polsterung muss schon beim ersten Bild stimmen
    await p.locator("body").click({ position: { x: 900, y: 300 } }).catch(() => {});
    await p.keyboard.press("BracketLeft");
    await p.waitForTimeout(400);
    console.log("nach [", await p.evaluate(() => getComputedStyle(document.querySelector(".pr-haupt")).paddingLeft), await p.evaluate(() => localStorage.getItem("oi-nav-schmal")));
    await p.goto(B + "/portal/admin/vorgaenge", { waitUntil: "commit" });
    await p.waitForSelector(".pr-haupt", { state: "attached" });
    const frueh = await p.evaluate(() => getComputedStyle(document.querySelector(".pr-haupt")).paddingLeft + " vorab=" + !!document.getElementById("oi-nav-vorab"));
    await p.waitForLoadState("load");
    await p.waitForTimeout(1500);
    const spaet = await p.evaluate(() => getComputedStyle(document.querySelector(".pr-haupt")).paddingLeft + " vorab=" + !!document.getElementById("oi-nav-vorab") + " schmal=" + document.querySelector(".pr-wurzel").classList.contains("pr-schmal"));
    console.log("frueh", frueh, "| spaet", spaet);
    await p.locator('#portal-navigation a[href="/portal/admin/aufgaben"]').hover();
    await p.waitForTimeout(300);
    await p.screenshot({ path: ziel("t3_admin_schmal_1440.png") });
    // Klick in der Navigation: Indikator gleitet
    await p.locator('#portal-navigation a[href="/portal/admin"]').click();
    await p.waitForURL(B + "/portal/admin", { timeout: 120000 });
    await p.waitForTimeout(1200);
    console.log("indikator", await p.evaluate(() => document.querySelector("#portal-navigation .pr-indikator")?.getAttribute("style")));
    await p.keyboard.press("BracketLeft");
    await p.waitForTimeout(300);
    console.log("zurueck", await p.evaluate(() => localStorage.getItem("oi-nav-schmal")));
    await ctx.close();
  }
  if (modus === "alles" || modus === "mobil") {
    const ctx = await konto("flaeche@example.com", 390);
    const p = await seite(ctx, "/portal");
    await p.screenshot({ path: ziel("t3_flaeche_390.png") });
    await p.getByRole("button", { name: /Benutzermenü|Flaeche|Fläche/ }).first().click().catch((e) => console.log("menue", e.message));
    await p.waitForTimeout(500);
    await p.screenshot({ path: ziel("t3_flaeche_menue_390.png") });
    await ctx.close();
  }
  if (modus === "alles" || modus === "investor") {
    const ctx = await konto("investor@example.com", 390);
    const p0 = await seite(ctx, "/portal/boerse");
    const href = await p0.evaluate(() => [...document.querySelectorAll('a[href^="/portal/boerse/P"]')].map((a) => a.getAttribute("href"))[0]);
    console.log("expose", href);
    if (href) {
      const p = await seite(ctx, href);
      await p.screenshot({ path: ziel("t3_expose_390.png") });
    }
    await ctx.close();
  }
} finally {
  await b.close();
}

