// T3: Server-HTML der Portalseiten prüfen (ohne Browser)
const B = "http://localhost:3100";
const [email, ...pfade] = process.argv.slice(2);
const r = await fetch(B + "/api/auth/login", { method: "POST", headers: { Origin: B, "Content-Type": "application/json" }, body: JSON.stringify({ email, passwort: "Demo-2026!" }) });
const keks = (r.headers.getSetCookie?.() || []).map((c) => c.split(";")[0]).join("; ");
console.log("login", email, r.status);
for (const p of pfade) {
  const t0 = Date.now();
  const s = await fetch(B + p, { headers: { Cookie: keks }, redirect: "manual", signal: AbortSignal.timeout(240000) });
  const h = await s.text();
  const marken = ["Application error", "Unhandled Runtime Error", "oi-nav-vorab", "Als Nächstes", "Heute zu tun", "pr-link-aktiv", "Datenraum anfragen", "Weitere", "pr-bn-indikator", "__next_error__"].filter((m) => h.includes(m));
  console.log(p, s.status, `${((Date.now() - t0) / 1000).toFixed(1)}s`, marken.join(", "), s.status >= 300 && s.status < 400 ? s.headers.get("location") : "");
  const m = h.match(/<title>([^<]*)<\/title>/);
  if (m) console.log("  title:", m[1]);
}

